function linkifyUrlsInDoc() {
  const ui = DocumentApp.getUi();


  // Prompt for font
  const fontPrompt = ui.prompt('Linkify URLs', 'Enter the font name (e.g., Arial, Kalam, Roboto):', ui.ButtonSet.OK_CANCEL);
  if (fontPrompt.getSelectedButton() !== ui.Button.OK) return;
  const font = fontPrompt.getResponseText().trim() || 'Kalam';


  // Prompt for color
  const colorPrompt = ui.prompt('Linkify URLs', 'Enter hex color code or name (e.g., #FF0000, blue, orange):', ui.ButtonSet.OK_CANCEL);
  if (colorPrompt.getSelectedButton() !== ui.Button.OK) return;
  const color = colorPrompt.getResponseText().trim() || '#FFFF00';


  // Prompt for underline option
  const underlinePrompt = ui.prompt('Linkify URLs', 'Underline URLs? Type "yes" or "no":', ui.ButtonSet.OK_CANCEL);
  if (underlinePrompt.getSelectedButton() !== ui.Button.OK) return;
  const underlineInput = underlinePrompt.getResponseText().trim().toLowerCase();
  const underline = underlineInput === 'yes';


  const doc = DocumentApp.getActiveDocument();
  const body = doc.getBody();
  const textElement = body.editAsText();
  const text = textElement.getText();


  const urlRegex = /(https?:\/\/[^\s]+)/g;
  let match;
  let matches = [];


  // Collect all URL matches
  while ((match = urlRegex.exec(text)) !== null) {
    matches.push({ url: match[0], start: match.index, end: match.index + match[0].length });
  }


  if (matches.length === 0) {
    ui.alert("No URLs found in the document.");
    return;
  }


  // Apply formatting from end to start
  for (let i = matches.length - 1; i >= 0; i--) {
    const { url, start, end } = matches[i];
    textElement.setLinkUrl(start, end - 1, url);
    textElement.setForegroundColor(start, end - 1, color);
    textElement.setUnderline(start, end - 1, underline);
    textElement.setFontFamily(start, end - 1, font);
  }


  ui.alert(`Linkified ${matches.length} URL(s) with your chosen formatting.`);
}


