<Program>


// Add Portal Section and Document Portal Menu
// Credits to Susbear
function onOpen() {
  var ui = DocumentApp.getUi();
  var menu = ui.createMenu('Custom Menu')
    .addItem('Add Portal Section', 'showPortalDialog')
    .addSeparator()
    .addItem('Document Portal', 'showLinkedDocsMenu')  
    .addToUi();
}


// Prompt for Google Doc links to add to the Portal Section
function showPortalDialog() {
  var ui = DocumentApp.getUi();
  var response = ui.prompt(
    "Portal Section",
    "Enter Google Doc links separated by commas:",
    ui.ButtonSet.OK_CANCEL
  );


  if (response.getSelectedButton() == ui.Button.OK) {
    var links = response.getResponseText().split(',').map(link => link.trim());
    if (links.length > 0) {
      savePortalLinks(links);
    }
  }
}


// Store portal links in the script properties
function savePortalLinks(newLinks) {
  var properties = PropertiesService.getScriptProperties();
  var storedLinks = properties.getProperty("portalLinks");


  var allLinks = storedLinks ? JSON.parse(storedLinks) : [];
  allLinks = [...new Set([...allLinks, ...newLinks])]; // Avoid duplicates


  properties.setProperty("portalLinks", JSON.stringify(allLinks));
}


// Fetch document title using its URL
function getDocTitle(docUrl) {
  try {
    var docId = docUrl.match(/[-\w]{25,}/)[0]; // Extract Google Doc ID
    var doc = DriveApp.getFileById(docId);
    return doc.getName();
  } catch (e) {
    return "Untitled Document"; // In case of errors (e.g., no access)
  }
}


// Display the links to other Google Docs in the custom menu
function showLinkedDocsMenu() {
  var ui = DocumentApp.getUi();
  var properties = PropertiesService.getScriptProperties();
  var storedLinks = properties.getProperty("portalLinks");


  if (!storedLinks) {
    ui.alert("No linked documents found.");
    return;
  }


  var links = JSON.parse(storedLinks);


  var menu = ui.createMenu('Document Portal');  // Changed name here


  links.forEach(function(link, index) {
    var title = getDocTitle(link);
    menu.addItem(title, 'openLinkedDoc'); // Single open function for all links
    menu.addItem("Delete " + title, 'deleteLink_' + index); // Add delete option
  });


  menu.addToUi();
}


// Function to open a linked document in a new tab using HTML dialog
function openLinkedDoc() {
  var ui = DocumentApp.getUi();
  var properties = PropertiesService.getScriptProperties();
  var storedLinks = properties.getProperty("portalLinks");


  if (!storedLinks) {
    ui.alert("No linked documents found.");
    return;
  }


  var links = JSON.parse(storedLinks);
  var docUrl = links[0]; // Select the first link (or adjust to pass index if necessary)


  var htmlOutput = HtmlService.createHtmlOutput('<script>window.open("' + docUrl + '", "_blank");google.script.host.close();</script>');
  ui.showModalDialog(htmlOutput, 'Opening Document...');
}


// Function to delete a link from the portal
function deleteLink_0() {
  deleteLink(0);
}


// More dynamic delete functions for each link
function deleteLink(index) {
  var properties = PropertiesService.getScriptProperties();
  var storedLinks = properties.getProperty("portalLinks");


  if (!storedLinks) {
    DocumentApp.getUi().alert("No linked documents found.");
    return;
  }


  var links = JSON.parse(storedLinks);
  links.splice(index, 1); // Remove the link from the array


  properties.setProperty("portalLinks", JSON.stringify(links)); // Save the updated list


  DocumentApp.getUi().alert("Link has been deleted from the portal.");


  // Refresh the menu
  onOpen();
}


