🐏 ExportSheet


ExportSheets
Made by Winner1zz
——————————————————
<Job> 
Ever want just a list of links your doc has? Well guess what! NOW YOU CAN! This code finds hyperlinks in your doc and exports them to a spreadsheet
(dont worry if it says “Exception: Cannot call DocumentApp.getUi() from this context” because if you just simply open the doc it’ll run normally


<Drawback>
Only works on 1 tab
Btw this works great with link generator i made


<Program> 


function onOpen() {
  // Update the "Admin Tools" menu in the Google Doc
  var ui = DocumentApp.getUi();
  ui.createMenu('Admin Tools')
    .addItem('Export Links to Sheet', 'exportLinksToSheet')
    .addToUi();
}
function exportLinksToSheet() {
  const ui = DocumentApp.getUi();
  const doc = DocumentApp.getActiveDocument();
  const body = doc.getBody();
  const text = body.editAsText();
  const textContent = text.getText();
  let links = [];
  // Find all hyperlinks with paragraph index
  let offset = 0;
  let paragraphIndex = -1;
  while (offset < textContent.length) {
    let url = text.getLinkUrl(offset);
    if (url) {
      let start = offset;
      let end = start;
      while (end < textContent.length && text.getLinkUrl(end) === url) {
        end++;
      }
      let linkText = textContent.substring(start, end);
      let element = body.findText(linkText, body.findText(linkText));
      let currentParagraphIndex = element ? body.getChildIndex(element.getElement().getParent()) : -1;
      if (currentParagraphIndex !== paragraphIndex) {
        paragraphIndex = currentParagraphIndex;
      }
      links.push({ text: linkText, url: url, paragraph: paragraphIndex + 1 });
      offset = end;
    } else {
      offset++;
    }
  }
  if (links.length === 0) {
    ui.alert('No hyperlinks found in the document.');
    return;
  }
  // Create new Google Sheet
  const sheet = SpreadsheetApp.create('Document Links Export - ' + new Date().toLocaleString());
  const spreadsheet = SpreadsheetApp.openById(sheet.getId());
  const activeSheet = spreadsheet.getActiveSheet();
  // Add headers
  activeSheet.getRange('A1:C1').setValues([['Display Text', 'URL', 'Paragraph Index']]).setFontWeight('bold');
  // Add link data
  let data = links.map(link => [link.text, link.url, link.paragraph]);
  activeSheet.getRange(2, 1, links.length, 3).setValues(data);
  // Auto-resize columns
  activeSheet.autoResizeColumns(1, 3);
  // Get Sheet URL
  const sheetUrl = spreadsheet.getUrl();
  ui.alert('Exported ' + links.length + ' link(s) to new Sheet: ' + sheetUrl);
}




