DoubleSpaceCleaner
Made by Sus
——————————————————
<Job>
Removes double spaces anywhere on a tab in a google doc 
(Literally just for cleaning)


<Drawback>
Only works on one tab, and doesn’t target anything in tables
<Program> 


function trulySafeRemoveExtraSpaces() {
  const body = DocumentApp.getActiveDocument().getBody();
  const totalElements = body.getNumChildren();


  for (let i = 0; i < totalElements; i++) {
    const element = body.getChild(i);
    if (element.getType() === DocumentApp.ElementType.PARAGRAPH) {
      const textElem = element.asParagraph().editAsText();
      let text = textElem.getText();
      let newText = text.replace(/\s{2,}/g, ' ');


      if (text !== newText) {
        for (let j = text.length - 1; j >= 0; j--) {
          if (text.substring(j - 1, j + 1).match(/\s{2}/)) {
            textElem.deleteText(j, j);
          }
        }
      }
    }
  }


  DocumentApp.getUi().alert('Extra spaces removed safely.');
}
















