// ---------- PORTAL SYSTEM ----------
function showLinkedDocsMenu() {
  const properties = PropertiesService.getScriptProperties();
  const storedLinks = properties.getProperty("portalLinks");
  const links = storedLinks ? JSON.parse(storedLinks) : [];


  const linkItems = links.map((link, index) => {
    const title = getDocTitle(link);
    return `<div style="margin-bottom: 8px;">
      <a href="${link}" target="_blank" style="text-decoration: none; color: #3367d6;">${title}</a>
      <span style="color: red; cursor: pointer; margin-left: 10px;" onclick="deleteLink(${index})">❌</span>
    </div>`;
  }).join('');


  const html = `
    <div style="font-family: Arial, sans-serif; padding: 10px;">
      <h3 style="margin-top: 0;">📄 Document Portal</h3>
      <div>${linkItems || '<p>No links available.</p>'}</div>
      <hr style="margin: 12px 0;">
      <input type="text" id="linkInput" placeholder="Paste Google Doc link" style="width: 100%; padding: 5px;" />
      <button onclick="addLink()" style="margin-top: 8px;">➕ Add Link</button>
      <script>
        function deleteLink(index) {
          if (confirm("Delete this link?")) {
            google.script.run.withSuccessHandler(() => location.reload()).deleteLinkByIndex(index);
          }
        }
        function addLink() {
          const input = document.getElementById("linkInput").value.trim();
          if (input) {
            google.script.run.withSuccessHandler(() => location.reload()).addPortalLink(input);
          } else {
            alert("Please enter a link.");
          }
        }
      </script>
    </div>
  `;


  DocumentApp.getUi().showSidebar(HtmlService.createHtmlOutput(html).setTitle("Portal Links"));
}


function addPortalLink(link) {
  const properties = PropertiesService.getScriptProperties();
  const storedLinks = properties.getProperty("portalLinks");
  const currentLinks = storedLinks ? JSON.parse(storedLinks) : [];
  if (!currentLinks.includes(link)) {
    currentLinks.push(link);
    properties.setProperty("portalLinks", JSON.stringify(currentLinks));
  }
}


function deleteLinkByIndex(index) {
  const properties = PropertiesService.getScriptProperties();
  const storedLinks = properties.getProperty("portalLinks");
  if (!storedLinks) return;
  const links = JSON.parse(storedLinks);
  links.splice(index, 1);
  properties.setProperty("portalLinks", JSON.stringify(links));
}


function getDocTitle(docUrl) {
  try {
