    'selenite': '65.109.112.222',
    'szvy central': '152.53.38.104'
    // Template for adding more proxies:
    // 'proxyName': 'IP_ADDRESS'
    // e.g., 'newproxy': '192.168.1.100'
  };


  // Prompt for number of links
  const numberResponse = ui.prompt('Generate Links', 'How many links?', ui.ButtonSet.OK_CANCEL);
  if (numberResponse.getSelectedButton() !== ui.Button.OK) return;
  const numberOfLinks = parseInt(numberResponse.getResponseText().trim());
  if (isNaN(numberOfLinks) || numberOfLinks <= 0) {
    ui.alert('Please enter a valid number greater than 0.');
    return;
  }


  // Prompt for proxy type
  const proxyResponse = ui.prompt('Generate Links', 'What type of proxy? (e.g., selenite, szvy central)', ui.ButtonSet.OK_CANCEL);
  if (proxyResponse.getSelectedButton() !== ui.Button.OK) return;
  const proxyType = proxyResponse.getResponseText().trim().toLowerCase();
  if (!proxies.hasOwnProperty(proxyType)) {
    ui.alert(`Invalid proxy type. Available proxies: ${Object.keys(proxies).join(', ')}`);
    return;
  }


  // Get the IP for the selected proxy
  const ip = proxies[proxyType];


  // Function to generate random alphanumeric string
  function generateRandomString(length) {
    const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let result = '';
    for (let i = 0; i < length; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
  }


  // Generate and insert links
  let generatedCount = 0;
  for (let i = 0; i < numberOfLinks; i++) {
    const randomName = generateRandomString(8);
    const url = `http://${randomName}.${ip.replace(/\./g, '-')}.nip.io`;
    const displayText = `${proxyType}-${randomName}`;
    const paragraph = body.appendParagraph(displayText);


    // Link the whole paragraph text correctly
    const text = paragraph.editAsText();
    text.setLinkUrl(0, displayText.length - 1, url);


    // Apply desired formatting
    text.setFontFamily(0, displayText.length - 1, 'Arial');
    text.setForegroundColor(0, displayText.length - 1, '#0000FF');
    text.setUnderline(0, displayText.length - 1, true);


    generatedCount++;
  }


  ui.alert(`Generated ${generatedCount} link(s) using ${proxyType}.`);
}






