//Credit to Fredrick Susbear the III
function linkifyUrlsInDoc() {
  var doc = DocumentApp.getActiveDocument();
  var body = doc.getBody();
  var text = body.getText();


  // Regular expression to match URLs
  var urlRegex = /(https?:\/\/[^\s]+)/g;
  var matches = [...text.matchAll(urlRegex)];


  if (matches.length === 0) {
    Logger.log("No URLs found in the document.");
    return;
  }


  var textElement = body.editAsText();


  // Loop through all found matches and apply the link and styling
  for (var i = matches.length - 1; i >= 0; i--) {
    var url = matches[i][0];
    var start = matches[i].index;
    var end = start + url.length;


    // Apply the hyperlink
    textElement.setLinkUrl(start, end - 1, url);


    // Apply white text color & remove underline
    textElement.setForegroundColor(start, end - 1, "#FFFFFF");  // White text
    textElement.setUnderline(start, end - 1, false);  // Remove underline
  }


  Logger.log("All URLs have been linked, set to white, and underlines removed!");
}


